                PricebookEntry pbe = pricebookEntries.get(pw.id);
                if (pbe != null) {
                    OrderItem item = new OrderItem(
                            OrderId = order.Id,
                            Product2Id = pw.id,
                            PricebookEntryId = pbe.Id,
                            Quantity = pw.quantity != null ? pw.quantity : 1,
                            UnitPrice = pbe.UnitPrice
                    );
                    orderItems.add(item);
                }
            }
            if (!orderItems.isEmpty()) {
                insert orderItems;
            }
            activateOrderAsync(order.Id, contract.Id);

            return order.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw new AuraHandledException('Error creating order: ' + e.getMessage());
        }
    }

    @future
    public static void activateOrderAsync(Id orderId, Id contractId) {
        try {
            Contract contractToUpdate = [SELECT Id, Status FROM Contract WHERE Id = :contractId];
            contractToUpdate.Status = 'Activated';
            update contractToUpdate;

            Order orderToUpdate = [SELECT Id, Status FROM Order WHERE Id = :orderId];
            orderToUpdate.Status = 'Activated';
            update orderToUpdate;

        } catch (Exception e) {
        }
    }

    public static Decimal getProductsTotalAmountAfterDiscount(List<ProductWrapper> products) {
        if (products == null || products.isEmpty()) {
            return 0;
        }

        List<Discount__c> activeDiscounts = [
                SELECT Id, Name, Discount_Type__c, Value_Type__c, Discount_Value__c,
                        Start_Date__c, End_Date__c,
                        Condition_Logic__c,
                        Recurring_Date_Start__c, Recurring_Date_End__c, Recurring_Date_Repeat_By__c
                FROM Discount__c
                WHERE Is_Active__c = TRUE
        ];
        Decimal totalAmount = getProductsTotalAmount(products);
        DiscountSettings settings = new DiscountSettings();

        return DiscountFilter.calculateDiscountedAmount(activeDiscounts,settings,  totalAmount);
    }
}

trigger AppliedDiscount on Applied_Discount__c (before insert, before update) {
    List<Applied_Discount__c> appliedDiscounts = Trigger.new;

}

trigger AppliedDiscount on Applied_Discount__c (before insert, before update) {
    List<Applied_Discount__c> appliedDiscounts = Trigger.new;

}

trigger AppliedDiscount on Applied_Discount__c (after insert, after update) {
    Set<Id> orderIds = new Set<Id>();
    for (Applied_Discount__c ad : Trigger.new) {
        if (ad.Order__c != null) {
            orderIds.add(ad.Order__c);
        }
    }
    if (orderIds.isEmpty()) return;

    // Get all Applied_Discount__c for affected Orders
    Map<Id, List<Applied_Discount__c>> orderToDiscounts = new Map<Id, List<Applied_Discount__c>>();
    for (Applied_Discount__c ad : [SELECT Id, Order__c, Amount_Discounted__c FROM Applied_Discount__c WHERE Order__c IN :orderIds]) {
        if (!orderToDiscounts.containsKey(ad.Order__c)) {
            orderToDiscounts.put(ad.Order__c, new List<Applied_Discount__c>());
        }
        orderToDiscounts.get(ad.Order__c).add(ad);
    }

    // Get Orders
    List<Order> ordersToUpdate = new List<Order>();
    for (Order o : [SELECT Id, TotalAmount, Order_Amount_After_Discount__c FROM Order WHERE Id IN :orderIds]) {
        List<Applied_Discount__c> discounts = orderToDiscounts.get(o.Id);
        if (discounts == null || discounts.isEmpty()) continue;
        Decimal maxDiscount = 0;
        for (Applied_Discount__c ad : discounts) {
            if (ad.Amount_Discounted__c != null && ad.Amount_Discounted__c > maxDiscount) {
                maxDiscount = ad.Amount_Discounted__c;
            }
        }
        o.Order_Amount_After_Discount__c = o.TotalAmount != null ? o.TotalAmount - maxDiscount : null;
        ordersToUpdate.add(o);
    }
    if (!ordersToUpdate.isEmpty()) {
        update ordersToUpdate;
    }
}
